// Extract and clean email data
const item = $input.first().json;

const extractText = (html) => {
  if (!html) return '';
  return html
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const extractedData = {
  email_id: item.id,
  thread_id: item.threadId,
  from: item.payload.headers.find(h => h.name === 'From')?.value || '',
  subject: item.payload.headers.find(h => h.name === 'Subject')?.value || '',
  date: item.payload.headers.find(h => h.name === 'Date')?.value || '',
  body_text: extractText(item.snippet || ''),
  has_attachments: (item.payload.parts?.some(p => p.filename) || false),
  labels: item.labelIds || [],
  received_at: new Date().toISOString()
};

// Extract email address
const emailMatch = extractedData.from.match(/<(.+?)>/);
extractedData.sender_email = emailMatch ? emailMatch[1] : extractedData.from;

// Combine subject and body for analysis
extractedData.full_text = `${extractedData.subject} ${extractedData.body_text}`;

return { json: extractedData };

// Process classification results and determine routing
const emailData = $input.first().json;
const classification = emailData[0]; // Hugging Face classification
const sentiment = emailData[1]; // Sentiment analysis

// Extract top category
const topCategory = classification.labels[0];
const topScore = classification.scores[0];

// Extract sentiment
const topSentiment = sentiment[0][0];
const sentimentScore = topSentiment.score;
const sentimentLabel = topSentiment.label; // POSITIVE or NEGATIVE

// Determine priority
let priority = 'medium';
if (sentimentLabel === 'NEGATIVE' && sentimentScore > 0.8) {
  priority = 'high';
} else if (['billing_question', 'refund_request', 'complaint'].includes(topCategory)) {
  priority = 'high';
} else if (['feature_request', 'general_inquiry'].includes(topCategory)) {
  priority = 'low';
}

// Determine Zendesk group and assignee
const routingMap = {
  'technical_support': { group_id: 123456, tags: ['technical', 'support'] },
  'billing_question': { group_id: 123457, tags: ['billing', 'finance'] },
  'account_issue': { group_id: 123458, tags: ['account', 'access'] },
  'feature_request': { group_id: 123459, tags: ['feature', 'product'] },
  'bug_report': { group_id: 123460, tags: ['bug', 'engineering'] },
  'general_inquiry': { group_id: 123461, tags: ['general', 'support'] },
  'complaint': { group_id: 123462, tags: ['complaint', 'escalation'] },
  'refund_request': { group_id: 123457, tags: ['refund', 'billing'] }
};

const routing = routingMap[topCategory] || routingMap['general_inquiry'];

const processedTicket = {
  ...emailData,
  category: topCategory,
  category_confidence: topScore,
  sentiment: sentimentLabel.toLowerCase(),
  sentiment_score: sentimentScore,
  priority: priority,
  zendesk_group_id: routing.group_id,
  tags: routing.tags,
  auto_response_needed: sentimentLabel === 'NEGATIVE' && sentimentScore > 0.8,
  escalation_needed: priority === 'high' && sentimentLabel === 'NEGATIVE'
};

return { json: processedTicket };

// Generate auto-response based on category
const ticket = $input.first().json;

const responseTemplates = {
  'technical_support': `Thank you for contacting technical support. We've received your inquiry and a specialist will review your case shortly. In the meantime, please check our knowledge base for immediate solutions.`,

  'billing_question': `Thank you for reaching out regarding your billing inquiry. Our billing team has been notified and will review your account. You should expect a response within 24 hours.`,

  'complaint': `We sincerely apologize for any inconvenience you've experienced. Your feedback is very important to us. A senior support specialist has been assigned to your case and will contact you shortly.`,

  'refund_request': `Thank you for your refund request. Our billing team will review your case according to our refund policy. You'll receive a response within 1-2 business days.`,

  'bug_report': `Thank you for reporting this issue. Our engineering team has been notified and will investigate. We'll keep you updated on the progress.`,

  'default': `Thank you for contacting us. We've received your message and will respond as soon as possible.`
};

const responseBody = responseTemplates[ticket.category] || responseTemplates['default'];

const autoResponse = {
  to: ticket.sender_email,
  subject: `Re: ${ticket.subject}`,
  body: `Dear Customer,\n\n${responseBody}\n\nTicket ID: ${ticket.zendesk_ticket_id}\nPriority: ${ticket.priority.toUpperCase()}\n\nBest regards,\nCustomer Support Team`,
  ticket_id: ticket.zendesk_ticket_id
};

return { json: autoResponse };

